// ─────────────────────────────────────────────────────────────────────────────
// Canvas
// ─────────────────────────────────────────────────────────────────────────────
struct Canvas
{
    std::vector<uint8_t> px;
    int w, h;

    // The vertical extent of everything drawn since the last fill().
    //
    // Tracked per DRAW CALL rather than per pixel — two comparisons for a whole
    // glyph — so visible_row_offset() below costs nothing measurable. Scanning
    // the finished bitmap for ink would be 756k pixel comparisons on a 2.5 ms
    // render, which is a fifth of the budget to learn something the drawing
    // code already knew.
    int ink_top = INT32_MAX;
    int ink_bottom = INT32_MIN;

    // The rows fill() and paint_margin() have actually painted, so the margin is
    // painted once and only as far as the shift needs.
    int filled_top = 0, filled_bottom = 0;

    Canvas(int w, int h) : px(w * h * CH), w(w), h(h) {}

    void note_ink(int y0, int y1)
    {
        if (y0 < 0) y0 = 0;
        if (y1 > h - 1) y1 = h - 1;
        if (y0 > y1) return;
        if (y0 < ink_top) ink_top = y0;
        if (y1 > ink_bottom) ink_bottom = y1;
    }

    // Fill the entire canvas with one colour.
    //
    // ONE 32-BIT STORE, NOT FOUR BYTE STORES, AND THE DIFFERENCE IS 1040 us PER
    // CARD -- a third of the whole request, measured on the deploy host with
    // both binaries running side by side and requests alternated between them.
    //
    // The byte-wise version could not be vectorised, and not because of the
    // vector width: a `uint8_t` store may alias `this->px`, `this->w` and
    // `this->h`, so the compiler must reload the vector's data pointer before
    // EVERY ONE of the four byte stores and re-read w and h each trip to
    // recompute the bound. Nine memory operations to write four bytes, 756,000
    // times a card. Hoisting the pointer and writing a whole pixel at a time
    // takes the aliasing question away, and clang then emits vpbroadcastd plus
    // four unrolled 64-byte AVX-512 stores -- 256 bytes an iteration.
    //
    // Two alternatives were built and measured on the box, and both are worse:
    //
    //   non-temporal stores (_mm256_stream_si256)  1.27x   vs the splat's 1.41x
    //   __builtin_assume_aligned(px.data(), 64)    SIGSEGV
    //
    // NT stores lose because the encoder reads this canvas back immediately, so
    // bypassing the cache only makes the filter pass fetch 3 MB from DRAM again.
    // The alignment hint is simply a lie -- std::vector's buffer is 16-byte
    // aligned, and promising 64 makes clang emit aligned AVX-512 stores that
    // fault on the first render.
    //
    // At ~56 us for 3.02 MB this is now writing at about 54 GB/s, faster than a
    // memcpy of the same buffer (69 us), because it only writes. There is
    // nothing further here: it is memory-bandwidth-bound.
    void fill(RGBA c)
    {
        // The memcpy below reproduces the byte order the four separate stores
        // wrote (r, g, b, a), on either endianness -- but only while RGBA is
        // exactly those four bytes with no padding. A fifth field, or an
        // alignment attribute, would silently paint the wrong colour.
        static_assert(sizeof(RGBA) == 4, "fill() packs RGBA into one 32-bit store");

        uint32_t packed;
        std::memcpy(&packed, &c, sizeof packed);

        // ONLY THE CARD'S OWN ROWS, not the whole padded canvas.
        //
        // Painting all 886 rows cost 40% more than the 630 that can be seen,
        // and measured SLOWER than the old pixel-slide on the booklet layout --
        // because that layout is already balanced, so the slide it replaced
        // returned immediately and cost nothing at all. The margin is painted
        // afterwards in paint_margin(), by exactly the number of rows the shift
        // turns out to need, which is usually a few dozen and often none.
        uint32_t *p = reinterpret_cast<uint32_t *>(px.data()) + (size_t)PAD * w;
        const size_t n = (size_t)w * VIS_H;
        for (size_t i = 0; i < n; ++i)
            p[i] = packed;

        filled_top = PAD;
        filled_bottom = PAD + VIS_H; // exclusive
        ink_top = INT32_MAX;
        ink_bottom = INT32_MIN;
    }

    // Paint whatever of the visible window falls outside what fill() painted.
    void paint_margin(RGBA c, size_t offset)
    {
        static_assert(sizeof(RGBA) == 4, "paint_margin packs RGBA into one store");
        uint32_t packed;
        std::memcpy(&packed, &c, sizeof packed);
        uint32_t *base = reinterpret_cast<uint32_t *>(px.data());

        const int want_top = (int)offset;
        const int want_bottom = (int)offset + VIS_H; // exclusive
        if (want_top < filled_top)
        {
            for (size_t i = (size_t)want_top * w, e = (size_t)filled_top * w; i < e; ++i)
                base[i] = packed;
            filled_top = want_top;
        }
        if (want_bottom > filled_bottom)
        {
            for (size_t i = (size_t)filled_bottom * w, e = (size_t)want_bottom * w; i < e; ++i)
                base[i] = packed;
            filled_bottom = want_bottom;
        }
    }

    // WHERE THE VISIBLE CARD STARTS, so that what was drawn sits centred.
    //
    // This replaced centre_vertically(), which MOVED THE PIXELS: 630 memcpys of
    // 4800 bytes each, sliding the whole canvas until the block was centred,
    // then repainting the band it vacated. That is 3 MB of memory traffic to
    // act on one integer, and it evicted the canvas from cache immediately
    // before the encoder read it back -- so it cost more than its own 97 us.
    //
    // The canvas is taller than the card instead. The composition is drawn from
    // a fixed anchor inside it and nothing moves; the encoder is handed a
    // pointer to whichever row leaves equal background above and below. The
    // rows outside the card are already background because fill() painted the
    // whole canvas.
    //
    // WHY THIS IS STILL "MEASURED, NOT TUNED", which is what the old comment
    // here was defending. The three layouts had top/bottom margins of 83/17,
    // 77/16 and 83/148 against side margins of 80 -- the invoice card was
    // bottom-starved from the day it was written, its total's descenders 16px
    // off the edge, and the booklet with no rows was bottom-heavy by the same
    // amount the other way. Each could have been fixed by moving constants
    // until it looked right, three times, and broken again by the next layout
    // change. The composition still stays anchored where it is written and the
    // finished block is still centred as a whole; only the mechanism changed.
    size_t visible_row_offset() const
    {
        if (ink_bottom < ink_top)
            return PAD; // nothing was drawn: the card is where the anchor is
        const int block = ink_bottom - ink_top + 1;
        if (block >= VIS_H)
            return PAD; // taller than the card; leave it at the anchor
        int start = ink_top - (VIS_H - block) / 2;
        if (start < 0)
            start = 0;
        if (start > h - VIS_H)
            start = h - VIS_H;
        return (size_t)start;
    }

    // The first pixel of the visible card. Rows are contiguous, so this is the
    // whole of the centring.
    const uint8_t *visible() const
    {
        return px.data() + visible_row_offset() * (size_t)w * CH;
    }

    // filled rectangle — no blending, solid
    void rect(int x, int y, int rw, int rh, RGBA c)
    {
        note_ink(y, y + rh - 1);
        for (int row = y; row < y + rh; ++row)
        {
            if (row < 0 || row >= h)
                continue;
            for (int col = x; col < x + rw; ++col)
            {
                if (col < 0 || col >= w)
                    continue;
                uint8_t *p = px.data() + (row * w + col) * CH;
                p[0] = c.r;
                p[1] = c.g;
                p[2] = c.b;
                p[3] = c.a;
            }
        }
    }

    // blit a greyscale glyph bitmap with alpha blend onto canvas
    void blit_glyph(const uint8_t *bmp, int bw, int bh,
                    int dx, int dy, RGBA c)
    {
        note_ink(dy, dy + bh - 1);
        for (int row = 0; row < bh; ++row)
        {
            for (int col = 0; col < bw; ++col)
            {
                int cx = dx + col, cy = dy + row;
                if (cx < 0 || cy < 0 || cx >= w || cy >= h)
                    continue;
                uint8_t alpha = bmp[row * bw + col];
                if (alpha == 0)
                    continue;
                uint8_t *p = px.data() + (cy * w + cx) * CH;
                // simple over blend
                uint16_t ia = 255 - alpha;
                p[0] = (uint8_t)((c.r * alpha + p[0] * ia) >> 8);
                p[1] = (uint8_t)((c.g * alpha + p[1] * ia) >> 8);
                p[2] = (uint8_t)((c.b * alpha + p[2] * ia) >> 8);
                p[3] = 255;
            }
        }
    }
};

// ─────────────────────────────────────────────────────────────────────────────
// UTF-8 — one validated decoder for all untrusted text
// ─────────────────────────────────────────────────────────────────────────────
// Decode one Unicode scalar from [p, end); advance p past what it consumed.
// Returns U+FFFD (REPLACEMENT CHARACTER) for every malformed, overlong,
// surrogate, or out-of-range sequence, consuming at least one byte on error so a
// hostile string always makes progress and can neither stall nor be read past
// `end`. This replaces the old ad-hoc decoder that understood only ₹ and fed
// every other multibyte byte through as a raw 0x80–0xFF "code point": that both
// garbled real Unicode names and was exactly the kind of unchecked byte-poking a
// crafted name could probe. The clamp to <= U+10FFFF keeps the value in range
// for stbtt, which returns an empty glyph for anything the font lacks.
static uint32_t next_utf8(const char *&p, const char *end)
{
    if (p >= end)
        return 0xFFFD;
    unsigned char b0 = (unsigned char)*p++;
    if (b0 < 0x80)
        return b0; // ASCII fast path

    uint32_t cp;
    int need;
    if ((b0 & 0xE0) == 0xC0) { cp = b0 & 0x1F; need = 1; }
    else if ((b0 & 0xF0) == 0xE0) { cp = b0 & 0x0F; need = 2; }
    else if ((b0 & 0xF8) == 0xF0) { cp = b0 & 0x07; need = 3; }
    else return 0xFFFD; // stray continuation byte or illegal 5/6-byte lead

    for (int i = 0; i < need; ++i)
    {
        if (p >= end)
            return 0xFFFD; // truncated at end of input
        unsigned char b = (unsigned char)*p;
        if ((b & 0xC0) != 0x80)
            return 0xFFFD; // not a continuation — resync WITHOUT consuming it
        cp = (cp << 6) | (uint32_t)(b & 0x3F);
        ++p;
    }

    static const uint32_t min_cp[4] = {0, 0x80, 0x800, 0x10000};
    if (cp < min_cp[need])       return 0xFFFD; // overlong encoding
    if (cp > 0x10FFFF)           return 0xFFFD; // outside Unicode
    if (cp >= 0xD800 && cp <= 0xDFFF) return 0xFFFD; // UTF-16 surrogate half
    return cp;
}

// ─────────────────────────────────────────────────────────────────────────────
// Font — thin wrapper around stbtt
// ─────────────────────────────────────────────────────────────────────────────
struct Font
{
    stbtt_fontinfo info;
    float scale = 0.f;
    int ascent = 0;
    int descent = 0;
    int line_gap = 0;

    bool load(const unsigned char *data)
    {
        if (!stbtt_InitFont(&info, data, 0))
            return false;
        return true;
    }

    void set_size(float px_height)
    {
        scale = stbtt_ScaleForPixelHeight(&info, px_height);
        stbtt_GetFontVMetrics(&info, &ascent, &descent, &line_gap);
    }

    // draw a UTF-8 string — returns x advance so caller knows where it ended
    // letter_spacing: extra pixels between glyphs (can be fractional via float)
    int draw(Canvas &canvas, const char *text, int x, int y,
             RGBA colour, float letter_spacing = 0.f) const
    {
        int baseline = y + (int)(ascent * scale);
        int cx = x;
        const char *p = text;
        const char *end = text + std::strlen(text);
        while (p < end)
        {
            uint32_t cp = next_utf8(p, end);
            const GlyphBitmap &g = glyph_get(&info, (int)cp, scale);
            if (!g.data.empty())
                canvas.blit_glyph(g.data.data(), g.w, g.h,
                                  cx + g.xoff, baseline + g.yoff, colour);
            cx += (int)(g.advance_f + letter_spacing);
        }
        return cx;
    }

    // measure string width without drawing
    int measure(const char *text, float letter_spacing = 0.f) const
    {
        int cx = 0;
        const char *p = text;
        const char *end = text + std::strlen(text);
        while (p < end)
        {
            uint32_t cp = next_utf8(p, end);
            const GlyphBitmap &g = glyph_get(&info, (int)cp, scale);
            cx += (int)(g.advance_f + letter_spacing);
        }
        return cx;
    }
};

// ─────────────────────────────────────────────────────────────────────────────
// Business-suffix helpers
// ─────────────────────────────────────────────────────────────────────────────

// Split a company name into {base, suffix}.  suffix is "" when not detected.
// Recognised suffixes (case-insensitive, must be preceded by space or comma):
//   Private Limited, Pvt. Ltd., Pvt Ltd, Limited, Ltd., Ltd
//   L.L.C., LLC,  L.L.P., LLP,  Inc., Inc,  Co., Co
static std::pair<std::string, std::string> split_business_suffix(const std::string &name)
{
    struct Entry
    {
        const char *lower;
        const char *display;
    };
    static const Entry table[] = {
        {"private limited", "Private Limited"},
        {"pvt. ltd.", "Pvt. Ltd."},
        {"pvt. ltd", "Pvt. Ltd"},
        {"pvt ltd.", "Pvt Ltd."},
        {"pvt ltd", "Pvt Ltd"},
        {"limited", "Limited"},
        {"ltd.", "Ltd."},
        {"ltd", "Ltd"},
        {"l.l.c.", "L.L.C."},
        {"llc", "LLC"},
        {"l.l.p.", "L.L.P."},
        {"llp", "LLP"},
        {"inc.", "Inc."},
        {"inc", "Inc"},
        {"co.", "Co."},
        {"co", "Co"},
        {nullptr, nullptr},
    };

    // lowercase copy for case-insensitive matching
    std::string low = name;
    for (auto &c : low)
        c = (char)std::tolower((unsigned char)c);

    for (int i = 0; table[i].lower; ++i)
    {
        const char *suf = table[i].lower;
        size_t suf_len = std::strlen(suf);
        if (low.size() <= suf_len)
            continue;

        // suffix must sit at the very end
        if (low.compare(low.size() - suf_len, suf_len, suf) != 0)
            continue;

        // the character immediately before the suffix must be a separator
        char sep = low[low.size() - suf_len - 1];
        if (sep != ' ' && sep != ',')
            continue;

        // base: everything before the separator, stripped
        std::string base = name.substr(0, low.size() - suf_len - 1);
        while (!base.empty() && (base.back() == ' ' || base.back() == ','))
            base.pop_back();

        return {base, table[i].display};
    }
    return {name, ""};
}

// ─────────────────────────────────────────────────────────────────────────────
// Card kinds — a CLOSED vocabulary, and the words live HERE
// ─────────────────────────────────────────────────────────────────────────────
// A card is rendered for a public, unauthenticated URL. The tempting way to
// support a second document type was `&label1=…&label2=…`, and it is the wrong
// one: caller-supplied labels turn a firm-branded endpoint into a general
// text-over-image renderer that anybody can point at anything, and every
// scraper that fetches it caches the result. So the caller names a KIND and the
// daemon holds the words, exactly as `theme_by_id` holds the palettes.
//
// An unknown kind falls back to Invoice rather than refusing — same reason
// theme_by_id returns THEMES[0]. A card that reads as an invoice when the
// caller mistyped is a cosmetic defect; a card that fails to render is a broken
// image in somebody's WhatsApp thread.
enum class CardKind
{
    Invoice,      // one bill: BILLED TO … / TOTAL PAYABLE …
    Booklet,      // a set, every invoice billed to the SAME party
    BookletMixed, // a set spanning several parties: headed by the ISSUER
};

static CardKind kind_by_id(const char *id)
{
    if (!id || !*id)
        return CardKind::Invoice;
    if (std::strcmp(id, "booklet") == 0)
        return CardKind::Booklet;
    if (std::strcmp(id, "booklet-mixed") == 0)
        return CardKind::BookletMixed;
    return CardKind::Invoice;
}

// The label above the name.
//
// "BILLED TO" is true of a single-party booklet — every invoice in it really is
// billed to that one party — so it carries over unchanged. It is NOT true when
// the set spans two counterparties, which the booklet schema permits; there the
// name is the issuing firm and the label has to say so, or the card states
// something false about who owes what.
//
// On a booklet the count joins it, because the count IS the subject: "4
// INVOICES BILLED TO / Erode Handloom Weavers" reads as one sentence. The
// renderer draws the numeral itself at twice this label's size — see step 4,
// which composes the two runs on a shared baseline.
static const char *name_label_tail(CardKind k)
{
    return k == CardKind::BookletMixed ? "FROM" : "BILLED TO";
}

// One line of the contents list: what it is, and what it came to.
//
// The card is a miniature of the page it links to, which is deliberately built
// as a cover and a TABLE OF CONTENTS with leader dots running to each amount.
// A booklet card that named one party and one total was not the whole story --
// a booklet may span several counterparties, and the reader deciding whether to
// open it deserves to see which.
//
// `label` is the page's own rule applied to a smaller space: the BILL NUMBER
// when every invoice is billed to the same party (repeating that party down
// three rows spends the widest column on a word the reader already knows), and
// the PARTY NAME when they are not. trunk decides which; the daemon just draws
// what it is handed, the same way it draws `company`.
struct ContentsRow
{
    std::string label;
    std::string amount;
};
static constexpr int MAX_CONTENTS_ROWS = 3;

// Everything one card render needs.
//
// A struct rather than another positional argument: render() was already at six
// and this adds seven more, at which point every call site is a row of values
// whose meaning is their order.
struct CardData
{
    std::string name;
    std::string amount;
    std::string date;
    CardKind kind = CardKind::Invoice;
    int count = 0;           // invoices in the set
    int more = 0;            // rows the card could not show
    std::string more_amount; // what those rows come to, so the list adds up
    ContentsRow rows[MAX_CONTENTS_ROWS];
    int row_count = 0;
};

// The label above the figure.
//
// "TOTAL PAYABLE" is a lie on a booklet the moment one of its invoices is
// settled, and a card outlives that payment: it is cached and forwarded by
// every app that touches it. What does NOT move is the total of the set —
// booklet membership is frozen when the link is created (see trunk's
// bill_link_collections.go: "a set somebody chose, not a query that keeps
// running") — so TOTAL BILLED is a figure the card may still be asserting
// correctly in six months, and the settled and due figures are deliberately
// not renderable here at all.
//
// The count now rides on the NAME label (see name_label_for), where it is a
// headline rather than small print, so this is just the two words.
static const char *amount_label_for(CardKind k)
{
    return k == CardKind::Invoice ? "TOTAL PAYABLE" : "TOTAL BILLED";
}

// Truncate text to fit max_w pixels, appending "…" if needed.
static std::string fit_or_truncate(Font &font, const std::string &text, int max_w)
{
    if (font.measure(text.c_str()) <= max_w)
        return text;
    std::string t = text;
    while (!t.empty() && font.measure((t + "\xe2\x80\xa6").c_str()) > max_w)
        t.pop_back();
    return t + "\xe2\x80\xa6"; // UTF-8 ellipsis U+2026
}

// fit_or_truncate for a TRACKED label.
//
// The label faces are drawn with letter_spacing, and measure() only accounts
// for tracking when it is told about it — so fitting a tracked string with the
// untracked helper above under-measures it by one tracking step per character
// and lets it run off the right edge, where blit_glyph clips it silently.
static std::string fit_or_truncate_tracked(Font &font, const std::string &text,
                                           int max_w, float tracking)
{
    if (font.measure(text.c_str(), tracking) <= max_w)
        return text;
    std::string t = text;
    while (!t.empty() && font.measure((t + "\xe2\x80\xa6").c_str(), tracking) > max_w)
        t.pop_back();
    return t + "\xe2\x80\xa6";
}

// Normalize/format incoming date strings into a human-friendly form:
// e.g. "2026-03-30" or "30 Mar 2026" -> "30 March 2026 Tuesday"
static std::string format_date_display(const std::string &in)
{
    auto trim = [](const std::string &s) -> std::string
    {
        size_t a = s.find_first_not_of(" \t\r\n");
        if (a == std::string::npos)
            return "";
        size_t b = s.find_last_not_of(" \t\r\n");
        return s.substr(a, b - a + 1);
    };

    std::string s = trim(in);
    if (s.empty())
        return s;

    // map month short -> number
    auto month_from_name = [](const std::string &mstr) -> int
    {
        if (mstr.empty())
            return -1;
        std::string low;
        for (char c : mstr)
            low.push_back((char)std::tolower((unsigned char)c));
        if (low.size() >= 3)
            low = low.substr(0, 3);
        static const char *tbl[] = {"jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"};
        for (int i = 0; i < 12; ++i)
            if (low == tbl[i])
                return i + 1;
        return -1;
    };

    int y = 0, m = 0, d = 0;

    // Try ISO-like YYYY-MM-DD
    if (sscanf(s.c_str(), "%d-%d-%d", &y, &m, &d) == 3 && y > 0 && m >= 1 && m <= 12 && d >= 1 && d <= 31)
    {
        // parsed successfully
    }
    else
    {
        // try space-separated tokens: "30 Mar 2026" or "2026 Mar 30"
        std::istringstream iss(s);
        std::string a, b, c;
        if (!(iss >> a))
            return in;
        if (!(iss >> b))
            return in;
        if (!(iss >> c))
            return in;

        // case: "d mon yyyy"
        if (c.size() == 4 && std::isdigit((unsigned char)c[0]))
        {
            try
            {
                d = std::stoi(a);
                m = month_from_name(b);
                y = std::stoi(c);
            }
            catch (...)
            {
                return in;
            }
        }
        // case: "yyyy mon d"
        else if (a.size() == 4 && std::isdigit((unsigned char)a[0]))
        {
            try
            {
                y = std::stoi(a);
                m = month_from_name(b);
                d = std::stoi(c);
            }
            catch (...)
            {
                return in;
            }
        }
        else
        {
            return in;
        }
        if (m < 1 || m > 12 || d < 1 || d > 31)
            return in;
    }

    // compute weekday using Zeller's congruence (Gregorian)
    int Y = y;
    int M = m;
    int D = d;
    if (M <= 2)
    {
        M += 12;
        Y -= 1;
    }
    int K = Y % 100;
    int J = Y / 100;
    int h = (D + (13 * (M + 1)) / 5 + K + (K / 4) + (J / 4) + (5 * J)) % 7;
    // Zeller: 0=Saturday,1=Sunday,2=Monday,...
    static const char *wday[] = {"Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"};

    static const char *month_name[] = {"January", "February", "March", "April", "May", "June",
                                       "July", "August", "September", "October", "November", "December"};

    std::string out = std::to_string(d) + " " + month_name[m - 1] + " " + std::to_string(y) + " " + wday[h];
    return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Renderer
// ─────────────────────────────────────────────────────────────────────────────
struct Renderer
{
    Font fraunces; // name
    Font dmmono;   // labels, date, amount digits
    Font inter;    // rupee symbol (clean glyph)

    // The canvas is allocated ONCE and reused across every render. The daemon
    // is single-threaded (one render in flight), the size is fixed, and
    // `render()` clears it with `fill()` before drawing — so there is no reason
    // to malloc/free ~3 MB of RGBA per request. A RENDER NOW ALLOCATES NOTHING
    // AT ALL: the PNG buffer below and the encoder's own scratch (see
    // src/fpng_card.cpp) are kept for the life of the process on the same
    // reasoning, which on the deploy host was worth 3.6x per card.
    Canvas canvas{IMG_W, CANVAS_H};

    // The encoded PNG, reused the same way. render() returns a reference to
    // this, so the three protocol handlers must bind it as `const auto &` —
    // `auto` would copy the bytes straight back out of the buffer that exists
    // to avoid copying them.
    std::vector<uint8_t> png;

    bool init()
    {
        fpng::fpng_init();
        if (!fraunces.load(assets_Fraunces_Bold_ttf))
        {
            fprintf(stderr, "[err] failed to load Fraunces\n");
            return false;
        }
        if (!dmmono.load(assets_DMMono_Medium_ttf))
        {
            fprintf(stderr, "[err] failed to load DM Mono\n");
            return false;
        }
        if (!inter.load(assets_Inter_VariableFont_opsz_wght_ttf))
        {
            fprintf(stderr, "[err] failed to load Inter\n");
            return false;
        }
        printf("[ok] renderer ready\n");
        return true;
    }

    // Draw one contents row: label on the left, amount on the right, leader
    // dots joining them.
    //
    // The dots are not decoration. Across a 1200px card the eye loses which
    // amount belongs to which name, which is the whole reason a printed
    // contents page has had them for centuries; the booklet's own HTML page
    // uses them for the same reason and this card is its miniature.
    //
    // Returns the y of the next row.
    // `muted` draws the row in the label ink rather than the body ink. The
    // remainder row uses it: "+2 ITEMS" is a summary of what is NOT listed, and
    // setting it in the same weight as the three real entries would read as a
    // fourth invoice belonging to a party called "+2 ITEMS".
    int draw_contents_row(Canvas &canvas, const ContentsRow &row, int y,
                          int left, int right, const Theme &theme, bool muted = false)
    {
        const int GAP = SPX(14); // clear space either side of the dots
        dmmono.set_size(SF(34.f));
        RGBA label_ink = muted ? theme.sub_label : theme.name;
        RGBA amount_ink = muted ? theme.sub_name : theme.amount;

        // The amount is drawn first and never truncated: a row whose figure is
        // cut off is worse than a row whose name is, because a shortened name
        // is obviously shortened and a shortened number is just a wrong number.
        int amount_w = dmmono.measure(row.amount.c_str());
        dmmono.draw(canvas, row.amount.c_str(), right - amount_w, y, amount_ink);

        // The label gets whatever is left, less room for at least a few dots.
        int label_max = right - amount_w - left - GAP * 2 - SPX(40);
        std::string label = fit_or_truncate(dmmono, row.label, label_max);
        int label_end = dmmono.draw(canvas, label.c_str(), left, y, label_ink);

        // Leader dots, one glyph at a time so the run ends on a whole dot
        // rather than a clipped half.
        int dot_w = dmmono.measure("·");
        if (dot_w > 0)
        {
            int baseline_y = y;
            for (int x = label_end + GAP; x + dot_w <= right - amount_w - GAP; x += dot_w)
                dmmono.draw(canvas, "·", x, baseline_y, theme.divider);
        }
        return y + SPX(44);
    }

    const std::vector<uint8_t> &render(const CardData &c, const Theme &theme)
    {
        const std::string &name = c.name;
        const std::string &amount = c.amount;
        const std::string &date = c.date;
        const CardKind kind = c.kind;

        // A contents list changes the whole vertical budget: the name and the
        // figure both give up size so three rows and their labels fit between
        // them. Without rows the card keeps the layout it has always had.
        const bool has_rows = c.row_count > 0;

// #if PROFILE
// #define PROF_LAP(label)                                                             \
//     do                                                                              \
//     {                                                                               \
//         auto _now = std::chrono::steady_clock::now();                               \
//         fprintf(stderr, "  [prof] %-22s %6.0f µs\n", label,                         \
//                 std::chrono::duration<double, std::micro>(_now - _prof_t).count()); \
//         _prof_t = _now;                                                             \
//     } while (0)
//         auto _prof_start = std::chrono::steady_clock::now();
//         auto _prof_t = _prof_start;
// #else
#define PROF_LAP(label) (void)0
        // #endif

        // Reuse the member canvas (allocated once); `fill` clears last render.
        Canvas &canvas = this->canvas;

        // ── 1. background ─────────────────────────────────────────────────────
        canvas.fill(theme.bg);
        PROF_LAP("canvas.fill");

        // NOTE: top accent bar removed — embedding apps control their own chrome.

        // ── layout constants ──────────────────────────────────────────────────
        const int LEFT = SPX(80);
        const int RIGHT = IMG_W - SPX(80); // for right-aligned date
        // Every vertical literal below is design-space, measured from the top of
        // the CARD -- which is row PAD of the canvas, not row 0. Two places
        // assign y absolutely instead of accumulating, and both must carry the
        // anchor: without it everything after them is drawn PAD rows too high
        // and the card comes out at 76/168 instead of 122/122. That is exactly
        // what tests/compare_renders.sh caught, and it is invisible by eye.
        const int TOP = PAD;
        int y = TOP;

        // ── 3. split name into base + optional business suffix ────────────────
        auto [base_name, suffix] = split_business_suffix(name);

        // ── 4. sub-label: "4 INVOICES BILLED TO" / "BILLED TO" / "FROM"
        //
        // THE NUMERAL IS DRAWN AT TWICE THE LABEL SIZE, and that is the point of
        // this line. The first booklet card put the count inside the small
        // tracked label over the figure, where "4 INVOICES" was the smallest
        // text on a card whose entire subject is that it is a SET -- the one
        // fact distinguishing it from the invoice card it otherwise resembles.
        //
        // The two runs share a BASELINE rather than a top edge: Font::draw takes
        // the top and derives the baseline from that face's ascent, so aligning
        // the tops of two sizes leaves the larger run sitting visibly low.
        y = TOP + SPX(72);
        int label_x = LEFT;
        int name_top = TOP + SPX(120);
        const char *label_tail = name_label_tail(kind);
        if (kind != CardKind::Invoice && c.count > 0)
        {
            char num[8];
            snprintf(num, sizeof(num), "%d", c.count);
            dmmono.set_size(SF(52.f));
            int big_baseline = y + (int)(dmmono.ascent * dmmono.scale);
            label_x = dmmono.draw(canvas, num, LEFT, y, theme.name, SF(1.f)) + SPX(12);

            dmmono.set_size(SF(28.f));
            int small_y = big_baseline - (int)(dmmono.ascent * dmmono.scale);
            char words[48];
            snprintf(words, sizeof(words), "%s %s", c.count == 1 ? "INVOICE" : "INVOICES", label_tail);
            dmmono.draw(canvas,
                        fit_or_truncate_tracked(dmmono, words, RIGHT - label_x, SF(3.5f)).c_str(),
                        label_x, small_y, theme.sub_label, SF(3.5f));
            // The numeral is taller than the label it replaces, so the name
            // below has to move down by the difference or it collides with the
            // descenders.
            name_top += SPX(20);
        }
        else
        {
            dmmono.set_size(SF(28.f));
            dmmono.draw(canvas,
                        fit_or_truncate_tracked(dmmono, label_tail, RIGHT - LEFT, SF(3.5f)).c_str(),
                        LEFT, y, theme.sub_label, SF(3.5f));
        }

        // The date shares that line, right-aligned, and says what it IS.
        //
        // It lived in the bottom-right corner of the canvas, then briefly on
        // the total's line — which works until the total's own figure moves to
        // the right margin to sit under a column of line items, and the two
        // collide. The header line has an empty right half in every layout, so
        // that is where it goes.
        //
        // "DUE" is not decoration. Unlabelled, a date in the corner of an
        // invoice reads as the invoice's date to most people, and this one is
        // the date the money is owed by. The card has room to say so.
        if (!date.empty())
        {
            char due[64];
            snprintf(due, sizeof(due), "DUE %s", date.c_str());
            dmmono.set_size(SF(26.f));
            int due_w = dmmono.measure(due, SF(1.5f));
            // Drawn only if it genuinely fits beside the label. Overlapping
            // two runs is worse than dropping the less important one, and a
            // scaled-down date beside a fixed-size label would be the only
            // text on the card whose size depends on the weekday.
            if (due_w <= RIGHT - label_x - SPX(40))
                dmmono.draw(canvas, due, RIGHT - due_w, y, theme.date, SF(1.5f));
        }
        PROF_LAP("name label");

        // ── 5. name (Fraunces Bold, auto-fitted) — allow larger max size
        const int NAME_MAX_W = RIGHT - LEFT;
        const float NAME_SZ_MAX = has_rows ? SF(76.f) : SF(110.f);
        const float NAME_SZ_MIN = has_rows ? SF(40.f) : SF(48.f);
        const float NAME_SZ_STEP = SF(4.f);

        // The suffix now sits BESIDE the name, so the name must leave room for
        // it. "Pvt Ltd" on its own line under "Anvaya Textiles" read as a
        // second fact about the company rather than the tail of its name, and
        // it spent a whole line -- about 40px of a 630px card -- on two words.
        const int SUFFIX_GAP = SPX(18);
        dmmono.set_size(SF(26.f));
        int suffix_w = suffix.empty() ? 0 : dmmono.measure(suffix.c_str(), SF(1.5f)) + SUFFIX_GAP;

        float name_sz = NAME_SZ_MAX;
        fraunces.set_size(name_sz);
        while (name_sz > NAME_SZ_MIN && fraunces.measure(base_name.c_str()) > NAME_MAX_W - suffix_w)
        {
            name_sz -= NAME_SZ_STEP;
            fraunces.set_size(name_sz);
        }
        std::string display_name = fit_or_truncate(fraunces, base_name, NAME_MAX_W - suffix_w);

        y = name_top;
        int name_end = fraunces.draw(canvas, display_name.c_str(), LEFT, y, theme.name);
        PROF_LAP("name draw");

        // compute bottom of name glyphs for next layout steps
        int name_baseline = y + (int)(fraunces.ascent * fraunces.scale);
        int name_bottom = name_baseline + (int)(std::abs(fraunces.descent) * fraunces.scale);

        // ── 6. business suffix, on the name's own BASELINE
        //
        // Set small and muted so it reads as the legal tail of the name rather
        // than competing with it, and aligned on the baseline rather than the
        // top: two sizes sharing a top edge leaves the smaller one floating
        // above the line the eye is following.
        if (!suffix.empty())
        {
            dmmono.set_size(SF(26.f));
            int suf_y = name_baseline - (int)(dmmono.ascent * dmmono.scale);
            dmmono.draw(canvas, suffix.c_str(), name_end + SUFFIX_GAP, suf_y, theme.sub_name, SF(1.5f));
            PROF_LAP("suffix draw");
            int suf_bottom = name_baseline + (int)(std::abs(dmmono.descent) * dmmono.scale);
            if (suf_bottom > name_bottom)
                name_bottom = suf_bottom;
        }

        // ── 7. divider line (moved up to reduce empty space)
        int divider_y = name_bottom + SPX(has_rows ? 26 : 36);
        canvas.rect(LEFT, divider_y, RIGHT - LEFT, std::max(1, SPX(1)), theme.divider);

        // ── 7b. the contents list, and what it could not fit
        if (has_rows)
        {
            int row_y = divider_y + SPX(26);
            for (int i = 0; i < c.row_count && i < MAX_CONTENTS_ROWS; ++i)
                row_y = draw_contents_row(canvas, c.rows[i], row_y, LEFT, RIGHT, theme);

            // THE REMAINDER IS A ROW, WITH ITS OWN FIGURE, and that is what
            // makes the list add up.
            //
            // Three rows over a booklet of five, with no overflow line at all,
            // is a card stating a complete contents list while missing two of
            // them -- a quiet lie, worse than an obviously partial one. But
            // "+2 MORE" with no figure beside it is only half a fix: the three
            // amounts shown plainly do not sum to the total underneath them,
            // and a reader who checks is left to wonder which number is wrong.
            // With the remainder carrying the value of what was elided, the
            // four figures on the card add up to the total exactly.
            //
            // "+2 ITEMS", not "+ 2 MORE": no space after the plus (DM Mono is
            // monospaced, so a space costs a full cell and the sign drifts away
            // from the number it belongs to), and "items" because they are
            // invoices that have a value, not merely more of something.
            if (c.more > 0)
            {
                char more_buf[32];
                snprintf(more_buf, sizeof(more_buf), "+%d %s", c.more,
                         c.more == 1 ? "ITEM" : "ITEMS");
                if (!c.more_amount.empty())
                {
                    row_y = draw_contents_row(canvas, {more_buf, c.more_amount},
                                              row_y, LEFT, RIGHT, theme, /*muted=*/true);
                }
                else
                {
                    // No remainder figure: an older trunk, which sent a count
                    // and nothing to put beside it. Say what is known rather
                    // than inventing the rest, and leave the row unaligned so
                    // it cannot be mistaken for a figure that was computed.
                    dmmono.set_size(SF(24.f));
                    dmmono.draw(canvas, more_buf, LEFT, row_y - SPX(6), theme.sub_label, SF(3.f));
                    row_y += SPX(30);
                }
            }
            divider_y = row_y + SPX(6);
            canvas.rect(LEFT, divider_y, RIGHT - LEFT, std::max(1, SPX(1)), theme.divider);
            PROF_LAP("contents rows");
        }

        // ── 8/9. the total: label on the left, figure on the right
        //
        // WHERE A TOTAL BELONGS IS UNDER THE FIGURES IT ADDS UP. The contents
        // card runs a column of amounts down the right edge and then set its
        // own total hard against the left margin, under nothing, leaving the
        // whole right half of the card empty below the rule. Stacking the label
        // over the figure cost a second line for two words as well.
        //
        // So it is one line: the label on the left where the row labels are,
        // the figure ending exactly where the row figures end. The eye runs
        // down the column and the total is waiting at the bottom of it.
        //
        // The card WITHOUT a contents list keeps the figure on the left, and
        // that is not an inconsistency. There, the amount is the subject of the
        // card rather than the sum of a column -- there is no column for it to
        // sit under -- and at 160px it spans most of the width anyway.
        const float RUPEE_RATIO = 0.7f; // rupee glyph ~70% of the digit size — a ratio, unscaled
        const int AMOUNT_SPACING = SPX(8);
        const float AMOUNT_SZ_MAX = has_rows ? SF(88.f) : SF(160.f);
        const float AMOUNT_SZ_MIN = SF(36.f);
        const float AMOUNT_SZ_STEP = SF(4.f);

        dmmono.set_size(SF(26.f));
        const char *amt_label = amount_label_for(kind);
        // Fitted rather than clipped: Canvas::blit_glyph clips glyph-by-glyph
        // without complaint, so an overlong label would leave a real figure
        // headed "TOTAL B" and nothing in any log.
        std::string amt_label_text = fit_or_truncate_tracked(dmmono, amt_label, RIGHT - LEFT, SF(3.5f));
        int amt_label_w = dmmono.measure(amt_label_text.c_str(), SF(3.5f));

        // On the shared line the figure competes with the label for width; on
        // its own line it has all of it.
        const int AMOUNT_MAX_W = has_rows ? (RIGHT - LEFT - amt_label_w - SPX(40)) : (RIGHT - LEFT);

        float amt_sz = AMOUNT_SZ_MAX;
        int total_w = 0;
        while (true)
        {
            dmmono.set_size(amt_sz);
            inter.set_size(amt_sz * RUPEE_RATIO);
            int rupee_w = inter.measure("₹");
            int digits_w = dmmono.measure(amount.c_str());
            total_w = rupee_w + AMOUNT_SPACING + digits_w;
            if (total_w <= AMOUNT_MAX_W || amt_sz <= AMOUNT_SZ_MIN)
                break;
            amt_sz -= AMOUNT_SZ_STEP;
        }

        int amount_y, amount_x;
        int total_label_y;
        if (has_rows)
        {
            amount_y = divider_y + SPX(22);
            amount_x = RIGHT - total_w; // flush with the column of row figures
            // The label rides the figure's BASELINE, not its top edge.
            int base = amount_y + (int)(dmmono.ascent * dmmono.scale);
            dmmono.set_size(SF(26.f));
            total_label_y = base - (int)(dmmono.ascent * dmmono.scale);
        }
        else
        {
            total_label_y = divider_y + SPX(24);
            amount_y = total_label_y + SPX(36);
            amount_x = LEFT;
        }
        dmmono.set_size(SF(26.f));
        dmmono.draw(canvas, amt_label_text.c_str(), LEFT, total_label_y, theme.amt_label, SF(3.5f));
        PROF_LAP("amount label");


        dmmono.set_size(amt_sz);
        inter.set_size(amt_sz * RUPEE_RATIO);
        int amount_baseline = amount_y + (int)(dmmono.ascent * dmmono.scale);
        int rupee_top = amount_baseline - (int)(inter.ascent * inter.scale);
        int rupee_end = inter.draw(canvas, "₹", amount_x, rupee_top, theme.rupee);
        dmmono.draw(canvas, amount.c_str(), rupee_end + AMOUNT_SPACING, amount_y, theme.amount);
        PROF_LAP("rupee + amount");

        // ── 11. balance the whole block, then encode ──────────────────────────
        //
        // Everything above composes downwards from a fixed top margin, which is
        // the readable way to write a layout and the wrong way to sit in a
        // frame: what ends up at the bottom is whatever is left over. Centring
        // here costs one row-wise move and makes every kind -- invoice,
        // booklet, booklet with no rows -- balanced by construction.
        const size_t vis = canvas.visible_row_offset();
        canvas.paint_margin(theme.bg, vis);
        PROF_LAP("centre — a pointer offset plus the margin the shift needs");

        // The output buffer is a member, kept across renders like the canvas
        // above it: after the first card its capacity already exceeds anything
        // a card compresses to, so a render allocates nothing at all.
        fpng::fpng_encode_card(canvas.px.data() + vis * (size_t)IMG_W * CH, IMG_W, IMG_H, CH, png);
        PROF_LAP("png encode");

// #if PROFILE
//         double _total_us = std::chrono::duration<double, std::micro>(
//                                std::chrono::steady_clock::now() - _prof_start)
//                                .count();
//         fprintf(stderr, "  [prof] %-22s %6.0f µs\n", "--- TOTAL ---", _total_us);
// #endif
#undef PROF_LAP
        return png;
    }
};

// ─────────────────────────────────────────────────────────────────────────────
// UDS daemon
// protocol: client sends  "name\tamount\tdate\n"
//           server replies <4 bytes LE PNG size><4 bytes LE render_us><PNG bytes>
// Cap untrusted inputs before they reach the C++ font shaper — shared by every
// protocol backend, so it lives OUTSIDE their #if guards. A 64 KB company name
// is a slow-render DoS and needless exposure of stb_truetype to attacker length,
// and the card only shows what fits anyway. Truncation, not rejection — a long
// name still renders (fitted/ellipsised), just bounded.
// Cap the byte length (a DoS bound on glyph work per request) and drop C0 control
// bytes + DEL. Newlines, tabs and NULs have no place on a one-line card and only
// perturb layout; everything >= 0x20 is kept and the UTF-8 decoder validates the
// multibyte sequences at draw time. Truncation, not rejection — a long name still
// renders (fitted/ellipsised). A sequence cut mid-way by the byte cap is harmless:
// next_utf8 yields a single U+FFFD at the boundary and never over-reads.
static void sanitize_field(std::string &s, size_t max_bytes)
{
    if (s.size() > max_bytes)
        s.resize(max_bytes);
    std::string out;
    out.reserve(s.size());
    for (unsigned char c : s)
        if (c >= 0x20 && c != 0x7F)
            out.push_back((char)c);
    s.swap(out);
}

// Hard input-length caps, grounded in what the card can PHYSICALLY render rather
// than in some round number. The name area is NAME_MAX_W wide; the font auto-fits
// DOWN to NAME_SZ_MIN and is then ellipsised by fit_or_truncate, so it holds only
// ~40-45 glyphs at the smallest size. 128 bytes sits comfortably above that for
// any script — so the visible cut is always the ellipsis, never this hard cap —
// while still being a quarter of the old limit, which bounds the glyph
// measure/fit work a hostile 5000-char name would otherwise cost. The amount is a
// paise integer (20 digits is already 10^18 rupees); the date is an ISO-ish
// string that format_date_display expands. Anything longer we literally cannot
// show, so we refuse to spend a single raster cycle on it — truncation upstream,
// ellipsis at draw.
static void bound_inputs(std::string &name, std::string &amount, std::string &date)
{
    sanitize_field(name, 128);
    sanitize_field(amount, 20);
    sanitize_field(date, 24);
}

// The booklet page count, or 0 for "do not say".
//
// Digits only, and bounded at four of them before anything is parsed: this is
// query-string input, `atoi` on a hostile string is unbounded work for us and
// free for the caller, and a booklet of more than 9999 invoices is not a
// booklet. Anything else — empty, signed, spaced, alphabetic, absurd — returns
// 0, and amount_label_for then drops the count from the label rather than
// printing a guess beside a real figure.
static int parse_count(const std::string &raw)
{
    if (raw.empty() || raw.size() > 4)
        return 0;
    int n = 0;
    for (unsigned char c : raw)
    {
        if (c < '0' || c > '9')
            return 0;
        n = n * 10 + (c - '0');
    }
    return n;
}

// The raw wire fields, before any of them are trusted.
//
// One struct so the three protocol backends collect the same set and hand it to
// the same builder. They used to each carry their own list of local strings,
// which is how a key added for one of them quietly did nothing in the others.
struct CardFields
{
    std::string company, amount, date, theme, kind, count, more, more_amount;
    std::string row_label[MAX_CONTENTS_ROWS];
    std::string row_amount[MAX_CONTENTS_ROWS];
};

// Bound, validate and convert the wire fields into what render() draws.
//
// Every cap is here rather than at the call sites, because the caps ARE the
// defence: this is untrusted text about to reach a C++ font shaper, and a limit
// that only one of three protocol backends applies is not a limit.
//
// A row is kept only when BOTH halves are present. A label with no figure is a
// contents line that says nothing, and a figure with no label is worse -- an
// amount floating against the right margin, attributable to nothing.
static CardData build_card(const CardFields &f)
{
    CardData c;
    c.name = f.company;
    c.amount = f.amount;
    c.date = f.date;
    bound_inputs(c.name, c.amount, c.date);

    c.kind = kind_by_id(f.kind.c_str());
    c.count = parse_count(f.count);
    c.more = parse_count(f.more);
    c.more_amount = f.more_amount;
    sanitize_field(c.more_amount, 20);

    // Contents rows on EITHER kind.
    //
    // They were refused on an invoice at first, on the reasoning that an
    // invoice is not a set — which confused the layout with the thing. A bill
    // has a contents list too: its line items, with the same shape (a label, a
    // figure, and a remainder for what did not fit) and the same arithmetic,
    // since `bills.amount` is the sum of its particulars' `total_price` and
    // the database has a test that says so. What separates the kinds is the
    // words, which is what `kind` was always for.
    {
        for (int i = 0; i < MAX_CONTENTS_ROWS; ++i)
        {
            std::string label = f.row_label[i], amount = f.row_amount[i];
            // Shorter than the headline name: this is a row in a three-column
            // rhythm, not the subject of the card, and the drawing code
            // ellipsises what will not fit anyway.
            sanitize_field(label, 64);
            sanitize_field(amount, 20);
            if (label.empty() || amount.empty())
                continue;
            c.rows[c.row_count].label = label;
            c.rows[c.row_count].amount = amount;
            ++c.row_count;
        }
    }
    return c;
}

// ─────────────────────────────────────────────────────────────────────────────
// Wire parsing — ONE decoder and ONE field parser for all three backends
// ─────────────────────────────────────────────────────────────────────────────
// These sat INSIDE the protocol #if blocks, duplicated between the FastCGI and
// HTTP backends. Two copies of a parser is two places a key has to be added,
// and the one nobody edits fails by silently ignoring the field -- which on a
// card looks like a layout that simply did not happen.

static std::string url_decode(const std::string &s)
{
    std::string r;
    for (int i = 0; i < (int)s.size();)
    {
        if (s[i] == '+')
        {
            r += ' ';
            ++i;
        }
        else if (s[i] == '%' && i + 2 < (int)s.size())
        {
            char h[3] = {s[i + 1], s[i + 2], 0};
            r += (char)strtol(h, nullptr, 16);
            i += 3;
        }
        else
            r += s[i++];
    }
    return r;
}

// Fields arrive as key=value pairs, from QUERY_STRING or a form-encoded body.
//
// The contents rows are r1..r3 with their amounts in a1..a3 rather than one
// packed "label|amount" value: an in-band separator is a character a company
// name is allowed to contain, and the first name containing it would split into
// two halves with no error anywhere.
static void parse_qs(const std::string &qs, CardFields &f)
{
    size_t pos = 0;
    while (pos < qs.size())
    {
        size_t amp = qs.find('&', pos);
        if (amp == std::string::npos)
            amp = qs.size();
        std::string pair = qs.substr(pos, amp - pos);
        size_t eq = pair.find('=');
        if (eq != std::string::npos)
        {
            std::string k = pair.substr(0, eq);
            std::string v = url_decode(pair.substr(eq + 1));
            if (k == "company")
                f.company = v;
            else if (k == "amount")
                f.amount = v;
            else if (k == "date")
                f.date = v;
            else if (k == "theme")
                f.theme = v;
            else if (k == "kind")
                f.kind = v;
            else if (k == "count")
                f.count = v;
            else if (k == "more")
                f.more = v;
            else if (k == "morea")
                f.more_amount = v;
            else if (k.size() == 2 && k[1] >= '1' && k[1] <= '0' + MAX_CONTENTS_ROWS)
            {
                if (k[0] == 'r')
                    f.row_label[k[1] - '1'] = v;
                else if (k[0] == 'a')
                    f.row_amount[k[1] - '1'] = v;
            }
        }
        pos = amp + 1;
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// ── Protocol backends ─────────────────────────────────────────────────────────
// Build with:
//   make release          → legacy UDS (default, tab-delimited)
//   make release PROTO=HTTP  → bare HTTP/1.0 over UDS
//   make release PROTO=FCGI  → FastCGI over UDS (nginx fastcgi_pass)

#if defined(PROTO_FCGI)

#pragma pack(push, 1)
struct FcgiHeader
{
    uint8_t version;
    uint8_t type;
    uint16_t request_id;  // big-endian
    uint16_t content_len; // big-endian
    uint8_t padding_len;
    uint8_t reserved;
};
#pragma pack(pop)

enum FcgiType : uint8_t
{
    FCGI_BEGIN_REQUEST = 1,
    FCGI_END_REQUEST = 3,
    FCGI_PARAMS = 4,
    FCGI_STDIN = 5,
    FCGI_STDOUT = 6,
};

static uint16_t be16(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }
static uint16_t to_be16(uint16_t v) { return (uint16_t)((v >> 8) | (v << 8)); }

static bool read_exact(int fd, uint8_t *dst, int n)
{
    while (n > 0)
    {
        int r = read(fd, dst, n);
        if (r <= 0)
            return false;
        dst += r;
        n -= r;
    }
    return true;
}

static void fcgi_write_record(int fd, uint8_t type, uint16_t req_id,
                              const uint8_t *data, uint16_t len)
{
    FcgiHeader hdr{};
    hdr.version = 1;
    hdr.type = type;
    hdr.request_id = to_be16(req_id);
    hdr.content_len = to_be16(len);
    write(fd, &hdr, sizeof(hdr));
    if (len)
        write(fd, data, len);
}

static std::string fcgi_extract_qs(const uint8_t *p, int len)
{
    int i = 0;
    while (i < len)
    {
        auto read_len = [&]() -> int
        {
            if (i >= len)
                return 0;
            if ((p[i] & 0x80) == 0)
                return p[i++];
            if (i + 4 > len)
                return 0;
            int v = ((p[i] & 0x7f) << 24) | (p[i + 1] << 16) | (p[i + 2] << 8) | p[i + 3];
            i += 4;
            return v;
        };
        int nlen = read_len(), vlen = read_len();
        if (i + nlen + vlen > len)
            break;
        std::string key((char *)p + i, nlen);
        i += nlen;
        std::string val((char *)p + i, vlen);
        i += vlen;
        if (key == "QUERY_STRING")
            return val;
    }
    return {};
}

static void handle_client_fcgi(int cli, Renderer &renderer)
{
    CardFields fields;
    std::string post_body;
    uint16_t req_id = 1;

    while (true)
    {
        FcgiHeader hdr;
        if (!read_exact(cli, (uint8_t *)&hdr, sizeof(hdr)))
            return;

        uint16_t clen = be16((uint8_t *)&hdr.content_len);
        req_id = be16((uint8_t *)&hdr.request_id);

        std::vector<uint8_t> body(clen + hdr.padding_len);
        if (!body.empty() && !read_exact(cli, body.data(), body.size()))
            return;

        if (hdr.type == FCGI_PARAMS && clen > 0)
        {
            std::string qs = fcgi_extract_qs(body.data(), clen);
            if (!qs.empty())
                parse_qs(qs, fields);
        }
        else if (hdr.type == FCGI_STDIN && clen > 0)
        {
            // A POSTed body, so a caller with a long name or an awkward
            // character is not forced to fit it into a URL somebody may log,
            // truncate or re-encode. Same keys, same closed vocabulary, same
            // percent-encoding: application/x-www-form-urlencoded, which
            // parse_qs already reads exactly. There is deliberately no JSON
            // parser here — this daemon renders untrusted input on a public
            // URL, and a hand-rolled parser is the last thing it needs.
            //
            // Bounded, and the excess is DROPPED rather than the connection:
            // the record loop must keep reading to the stream terminator or
            // the FastCGI conversation desyncs and nginx reports a 502 with no
            // explanation. What fits is 8 KB, which is two orders of magnitude
            // above the ~200 bytes six bounded fields can occupy.
            static constexpr size_t MAX_BODY = 8192;
            if (post_body.size() < MAX_BODY)
                post_body.append((const char *)body.data(),
                                 std::min<size_t>(clen, MAX_BODY - post_body.size()));
        }
        else if (hdr.type == FCGI_STDIN && clen == 0)
            break; // end of request
    }

    // The body is parsed AFTER the query string, so a key given in both is
    // taken from the body: it is the more deliberate half of the request, and
    // a caller who posts a name has said what they meant more clearly than a
    // URL that may have been assembled by something else.
    if (!post_body.empty())
        parse_qs(post_body, fields);

    if (fields.company.empty())
    {
        // A REAL 400, not silence.
        //
        // This used to `return`, which drops the connection mid-conversation:
        // nginx turns that into a 502 with nothing in either log, and a
        // scraper renders it as a broken image. Now that the endpoint is
        // public and universal (taxifo.com/preview.png) the caller is not
        // always trunk, and "you gave me no company" is worth saying out loud.
        static const char kNoName[] =
            "Status: 400 Bad Request\r\n"
            "Content-Type: text/plain; charset=utf-8\r\n\r\n"
            "company is required\n";
        fcgi_write_record(cli, FCGI_STDOUT, req_id, (const uint8_t *)kNoName, sizeof(kNoName) - 1);
        fcgi_write_record(cli, FCGI_STDOUT, req_id, nullptr, 0);
        uint8_t end400[8] = {};
        fcgi_write_record(cli, FCGI_END_REQUEST, req_id, end400, 8);
        return;
    }

    CardData card = build_card(fields);
    const Theme &theme = fields.theme.empty()
                             ? theme_for_amount(parse_amount_to_paise(card.amount.c_str()))
                             : theme_by_id(fields.theme.c_str());

    card.date = format_date_display(card.date);
    // No per-request logging: this is a hot path serving untrusted input, a log
    // line per card is wasted I/O (and, in a long-lived process, would sit in a
    // never-flushed stdout buffer). Only startup and errors are logged.
    const auto &png = renderer.render(card, theme);

    // STDOUT: headers + body (chunk if > 65535)
    char hdrs[256];
    int hlen = snprintf(hdrs, sizeof(hdrs),
                        "Content-Type: image/png\r\nContent-Length: %zu\r\n\r\n", png.size());
    fcgi_write_record(cli, FCGI_STDOUT, req_id, (uint8_t *)hdrs, (uint16_t)hlen);

    // chunk PNG into 65535-byte records
    size_t sent = 0;
    while (sent < png.size())
    {
        uint16_t chunk = (uint16_t)std::min<size_t>(65535, png.size() - sent);
        fcgi_write_record(cli, FCGI_STDOUT, req_id, png.data() + sent, chunk);
        sent += chunk;
    }

    fcgi_write_record(cli, FCGI_STDOUT, req_id, nullptr, 0); // end stream
    uint8_t end[8] = {};
    fcgi_write_record(cli, FCGI_END_REQUEST, req_id, end, 8);
}

#elif defined(PROTO_HTTP)

static void handle_client_http(int cli, Renderer &renderer)
{
    // read only first line
    char buf[2048] = {};
    int i = 0;
    char c;
    while (i < (int)sizeof(buf) - 1)
    {
        if (read(cli, &c, 1) <= 0)
            break;
        buf[i++] = c;
        if (i >= 2 && buf[i - 2] == '\r' && buf[i - 1] == '\n')
            break;
    }

    char *q = strchr(buf, '?');
    char *sp = q ? strchr(q, ' ') : nullptr;
    if (!q || !sp)
    {
        close(cli);
        return;
    }

    std::string qs(q + 1, sp);
    CardFields fields;
    parse_qs(qs, fields);

    if (fields.company.empty())
    {
        const char *r400 = "HTTP/1.0 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
        write(cli, r400, strlen(r400));
        return;
    }

    CardData card = build_card(fields);
    const Theme &theme = fields.theme.empty()
                             ? theme_for_amount(parse_amount_to_paise(card.amount.c_str()))
                             : theme_by_id(fields.theme.c_str());

    card.date = format_date_display(card.date);
    const auto &png = renderer.render(card, theme);

    char hdr[256];
    int hl = snprintf(hdr, sizeof(hdr),
                      "HTTP/1.0 200 OK\r\nContent-Type: image/png\r\nContent-Length: %zu\r\n\r\n",
                      png.size());
    write(cli, hdr, hl);
    write(cli, png.data(), png.size());
}

#endif

#if !defined(PROTO_FCGI) && !defined(PROTO_HTTP)
// Legacy tab-delimited UDS protocol, extracted into a function so the fork loop
// wraps it like the others. Does NOT close cli — the caller does.
static void handle_client_tab(int cli, Renderer &renderer)
{
    char buf[512] = {};
    read(cli, buf, sizeof(buf) - 1);
    std::string req(buf);
    if (!req.empty() && req.back() == '\n')
        req.pop_back();

    // Positional, tab-separated, trailing fields optional:
    //   name \t amount \t date [\t theme [\t kind [\t count]]]
    //
    // Split once rather than chained find()s: the old hand-unrolled version
    // handled exactly three and four fields, and every field added past that
    // was another nested branch. name and amount are required; everything
    // after date is a refinement the caller may omit.
    std::vector<std::string> f;
    for (size_t pos = 0;;)
    {
        size_t t = req.find('\t', pos);
        if (t == std::string::npos)
        {
            f.push_back(req.substr(pos));
            break;
        }
        f.push_back(req.substr(pos, t - pos));
        pos = t + 1;
    }
    if (f.size() < 3)
        return;
    auto field = [&f](size_t i) -> std::string { return i < f.size() ? f[i] : std::string(); };

    CardFields fields;
    fields.company = f[0];
    fields.amount = f[1];
    fields.date = f[2];
    fields.theme = field(3);
    fields.kind = field(4);
    fields.count = field(5);
    // The contents rows stop here, deliberately. They are six more positional
    // fields on a protocol whose only remaining virtue is that it is simple,
    // and it has no caller left: trunk's client for it was deleted with
    // /bills/preview/{uuid}. A booklet card asked for over this protocol gets
    // the name-and-total layout, which is what it did before rows existed.

    CardData card = build_card(fields);
    const Theme &theme = fields.theme.empty()
                             ? theme_for_amount(parse_amount_to_paise(card.amount.c_str()))
                             : theme_by_id(fields.theme.c_str());

    card.date = format_date_display(card.date);
    const auto &png = renderer.render(card, theme);
    uint32_t sz = (uint32_t)png.size();
    uint32_t render_us = 0;
    write(cli, &sz, 4);
    write(cli, &render_us, 4);
    write(cli, png.data(), png.size());
}
#endif

// Protocol dispatch, selected at compile time.
static void handle_client(int cli, Renderer &renderer)
{
#if defined(PROTO_FCGI)
    handle_client_fcgi(cli, renderer);
#elif defined(PROTO_HTTP)
    handle_client_http(cli, renderer);
#else
    handle_client_tab(cli, renderer);
#endif
}

// ─────────────────────────────────────────────────────────────────────────────
// run_daemon — ONE process, connections served sequentially, no fork
//
// This banner said "forks per connection so one bad input cannot crash the
// daemon" for months, directly above the code and the comment explaining that
// the fork was REMOVED and why. Fixed 2026-09-12.
// ─────────────────────────────────────────────────────────────────────────────
void run_daemon(Renderer &renderer)
{
    // Socket path from the environment, so the hardened unit can place it under
    // a RuntimeDirectory (/run/billpreview/) instead of world-writable /tmp;
    // defaults to SOCKET_PATH for the dev harness and back-compat.
    const char *sock = getenv("BILLPREVIEW_SOCKET");
    if (!sock || !*sock)
        sock = SOCKET_PATH;

    unlink(sock);
    int srv = socket(AF_UNIX, SOCK_STREAM, 0);
    if (srv < 0)
    {
        perror("socket");
        return;
    }

    sockaddr_un addr{};
    addr.sun_family = AF_UNIX;

    // THE PATH IS COPIED BY HAND, AND strncpy HERE WAS A REAL CRASH.
    //
    // zig's libc implements the strn* family by scanning the source for the
    // terminator with 64-byte AVX-512 loads (`mem.findScalarPos`, one
    // `vpcmpeqb (%rsi,%r8), %zmm0, %k1`), which reads up to 63 bytes PAST the
    // NUL. Our source is an ENVIRONMENT string, and environment strings sit at
    // the very top of the initial stack -- so whenever the path happens to end
    // within 64 bytes of that boundary the scan crosses into unmapped memory
    // and the daemon takes a SIGSEGV here, after `socket()` and before `bind`,
    // having printed "[ok] renderer ready" and nothing else.
    //
    // Measured on the deploy host: 100% reproducible for some environments and
    // 0% for others, the discriminator being the SIZE of the environment block
    // (adding 4 KB of padding to it moves the string off the boundary and the
    // crash disappears). It was present in every build back to the first, and
    // in the binary running in production -- which survives only because its
    // unit passes one short variable and systemd's own additions sit above it.
    // A future Environment= line in that unit is a crash loop under
    // Restart=always.
    //
    // So: our own bounded scan, which cannot read past the NUL, and a REFUSAL
    // rather than a truncation. A silently shortened socket path is a daemon
    // listening where nginx is not looking, which presents as the daemon being
    // down -- exactly the class of failure this file keeps a note about.
    size_t path_len = 0;
    while (path_len < sizeof(addr.sun_path) && sock[path_len] != '\0')
        ++path_len;
    if (path_len >= sizeof(addr.sun_path))
    {
        fprintf(stderr, "[err] socket path is %zu bytes; the limit is %zu\n",
                path_len, sizeof(addr.sun_path) - 1);
        return;
    }
    memcpy(addr.sun_path, sock, path_len); // addr{} zeroed it, so it stays terminated

    if (bind(srv, (sockaddr *)&addr, sizeof(addr)) < 0)
    {
        perror("bind");
        return;
    }
    // A generous backlog: this daemon serves connections sequentially in one
    // long-lived process (no fork, no threads), so a burst of link-unfurls queues
    // in the kernel while each ~15 ms render completes rather than being refused.
    listen(srv, 128);

#if defined(PROTO_FCGI)
    printf("[ok] listening on %s  [FCGI]\n", sock);
#elif defined(PROTO_HTTP)
    printf("[ok] listening on %s  [HTTP]\n", sock);
#else
    printf("[ok] listening on %s  [UDS]\n", sock);
#endif
    fflush(stdout);

    // ONE long-lived process, connections served sequentially. We deliberately do
    // NOT fork per connection: a fork-per-request model turns "send a malformed
    // name" into a fork + page-table setup + crash + stack-unwind + reap cycle we
    // pay for and the attacker does not — a cheap way to spin up a storm of
    // processes whose only job is to die. The defence here is PREVENTION, not
    // containment: the parse path is made total (validated UTF-8 in Font::draw,
    // every raster write clipped in Canvas, inputs bounded in bound_inputs) so no
    // input reaches undefined behaviour, and the catch below converts any C++
    // exception (bad_alloc, length_error, ...) into a dropped request instead of
    // a std::terminate. The process stays up; the glyph cache persists across
    // requests instead of being discarded with every child; the systemd sandbox
    // plus Restart=always remain the backstop for a genuine (non-input) fault.
    while (true)
    {
        int cli = accept(srv, nullptr, nullptr);
        if (cli < 0)
            continue;

        try
        {
            handle_client(cli, renderer);
        }
        catch (const std::exception &e)
        {
            // A malformed request must never take the daemon down. Log for the
            // operator, drop this one connection (nginx returns 502 for it), serve
            // the next. Anything reaching here is an allocation/size failure, not a
            // memory-safety bug — those are prevented upstream, not caught.
            fprintf(stderr, "[err] handler exception: %s\n", e.what());
        }
        catch (...)
        {
            fprintf(stderr, "[err] handler exception (non-std)\n");
        }
        close(cli);
    }
}

// Pre-warm the glyph cache with a few representative cards BEFORE the accept loop
// starts, so the first real request is not cold. The hot, fixed-scale glyphs —
// the "BILLED TO"/"TOTAL PAYABLE" labels, the date, common Latin/digits — are
// rasterised once here and, because this is now a single long-lived process,
// persist in the cache for the daemon's whole life (the bounded LRU-ish clear in
// glyph_get is the only thing that ever evicts them).
static void prewarm(Renderer &r)
{
    struct Sample
    {
        const char *name, *amount, *date;
        CardKind kind;
        int count;
        bool rows;
    };
    // Both kinds, because their labels do not share glyphs: a booklet's
    // "INVOICES / TOTAL BILLED" has no overlap with "TOTAL PAYABLE" beyond
    // T, O, A and L, and a cold booklet render would pay to rasterise the
    // rest on the first customer who opens one.
    static const Sample samples[] = {
        {"Acme Industries Private Limited", "1234567", "2026-09-01", CardKind::Invoice, 0, false},
        {"Zeta Traders LLP", "999", "2026-01-15", CardKind::Invoice, 0, false},
        {"A", "50000000", "2026-12-31", CardKind::Invoice, 0, false},
        {"Acme Industries Private Limited", "7,08,000.00", "", CardKind::Booklet, 6, true},
        {"Deshpande & Iyer Associates", "7,08,000.00", "", CardKind::BookletMixed, 12, true},
    };
    for (const auto &s : samples)
    {
        CardData c;
        c.name = s.name;
        c.amount = s.amount;
        c.date = format_date_display(s.date);
        c.kind = s.kind;
        c.count = s.count;
        if (s.rows)
        {
            // The contents rows are their own glyph run at their own size, so a
            // cold booklet render would rasterise the whole row face on the
            // first customer who opened one.
            c.rows[0] = {"Kannan Textiles Pvt Ltd", "1,20,000.00"};
            c.rows[1] = {"INV-1042", "84,702.17"};
            c.rows[2] = {"Devi Traders", "64,106.51"};
            c.row_count = 3;
            c.more = 1;
            c.more_amount = "31,437.06";
        }
        const Theme &t = theme_for_amount(parse_amount_to_paise(c.amount.c_str()));
        (void)r.render(c, t);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
int main()
{
    Renderer r;
    if (!r.init())
        return 1;
    prewarm(r);
    run_daemon(r);
    return 0;
}